//
// Wheel-event normalization shared by every camera surface in ce-cad.
// Dependency-free. Imported by vendor/OrbitControls.js (which serves both the
// :8765 dashboard viewport and the :8861 live page via live/server.py's
// /vendor/ route — that route is why this file lives in web/vendor/).
//
// Why: macOS trackpads emit high-frequency wheel events with SMALL pixel
// deltas (deltaMode 0, ~2-10px each); mice emit one ~120px notch (or
// deltaMode 1 lines). Code tuned for notches feels glacial on a trackpad.
// macOS pinch-to-zoom arrives as a wheel event with ctrlKey=true and small
// deltas, and needs its own (higher) gain.

// Pixels per unit for the non-pixel delta modes.
export const LINE_PX = 16;    // deltaMode 1 (lines) — Firefox default line height
export const PAGE_PX = 100;   // deltaMode 2 (pages)
export const NOTCH_PX = 120;  // one classic mouse-wheel notch, in pixels

// Exponent-per-normalized-pixel for zoom = exp(-|dy| * k * zoomSpeed).
export const ZOOM_K = {
  // notch: matches the OLD OrbitControls response exactly at dPR=1.
  //   Old: Math.pow(0.95, zoomSpeed * |d| / 100) = exp(-|d| * zoomSpeed * ln(1/0.95)/100)
  //   so k = ln(1/0.95)/100 = 5.1293e-4. One 120px notch keeps its old step
  //   0.95^(1.2*zoomSpeed) (~5.9% zoom at zoomSpeed 1, ~4.8% at 0.9).
  notch: Math.log(1 / 0.95) / 100,
  // track: trackpad two-finger scroll. Tuned so 53px of finger travel equals
  //   one old mouse notch: k = (120 * notch) / 53 = 1.1614e-3 (2.264x notch).
  //   The old code's /(100*devicePixelRatio|0) made a 4px trackpad tick worth
  //   ~0.05% zoom on a Retina Mac — this makes it worth 4/53 of a notch.
  track: (NOTCH_PX * Math.log(1 / 0.95) / 100) / 53,
  // pinch: macOS pinch-to-zoom (ctrlKey wheel). A full pinch gesture is
  //   roughly 150-250px of total deltaY; 0.004 makes that a 1.8x-2.7x zoom.
  pinch: 0.004,
};

// normalizeWheel(event) -> { dx, dy, pixels: true, pinch, coarse }
//   dx/dy    delta in PIXELS regardless of the event's deltaMode
//   pinch    true for macOS pinch-to-zoom (ctrlKey wheel with fine deltas)
//   coarse   true for discrete mouse-notch-style input (deltaMode 1/2, or a
//            pixel delta >= 100 — one classic notch is 100-120px); false for
//            trackpad-style fine deltas, momentum ticks included.
export function normalizeWheel(event) {
  const mode = event.deltaMode || 0;
  const m = mode === 1 ? LINE_PX : mode === 2 ? PAGE_PX : 1;
  const dx = (event.deltaX || 0) * m;
  const dy = (event.deltaY || 0) * m;
  const coarse = mode !== 0 || Math.abs(dy) >= 100;
  // ctrl+mouse-notch (Windows/Linux zoom convention) stays coarse, not pinch:
  // pinch gain on a full 120px notch would be a violent 38% step.
  const pinch = event.ctrlKey === true && !coarse;
  return { dx, dy, pixels: true, pinch, coarse };
}

// zoomScaleFor(normalized, zoomSpeed) -> multiplicative dolly scale in (0, 1].
// Exponential in the delta, so per-event responses compose: a burst of small
// trackpad events multiplies to exactly what one big event of the summed
// delta would give, and momentum tails decay gently by construction.
export function zoomScaleFor(w, zoomSpeed = 1) {
  const k = w.pinch ? ZOOM_K.pinch : (w.coarse ? ZOOM_K.notch : ZOOM_K.track);
  return Math.exp(-Math.abs(w.dy) * k * zoomSpeed);
}
